library_register_drm_tooltip: "Sama seperti Tambahkan ke layar beranda, tetapi pertama-tama mem-patch applicationDrmType sumber menjadi \"standard\" — mengubah file sumber. Gunakan hanya jika penambahan biasa gagal dengan kesalahan DRM.",
