installed_kstuff_off_body: "Payload tidak punya baca/tulis kernel, artinya titik masuk jailbreak/kstuff belum dimuat. Meluncurkan (dan memasang) game fpkg akan gagal sampai Anda memuat konsol lewat kstuff dan menyambung ulang.",
