activity_preparing_hint: "Menyiapkan… belum ada data yang ditransfer. Arsip terkompresi (.zip, .7z, .rar, .tar.zst, dan tar lainnya) diekstrak dulu di komputer Anda — untuk berkas besar ini bisa memakan waktu sebelum kecepatan unggah muncul.",
