err_fs_read_path_not_allowed: "Berkas ini berada di partisi sistem hanya-baca yang biasanya diblokir. Aktifkan Pengaturan → “Izinkan mengunduh berkas sistem” untuk membaca dari /system, /system_data, dan jalur terlindungi lainnya. Ini hanya memengaruhi unduhan — menghapus, memindahkan, dan menulis tidak pernah diizinkan di sana.",
err_rar_open_failed: "Tidak dapat membaca arsip RAR ini. Semua volume tampaknya ada, jadi arsipnya sendiri mungkin rusak atau memakai fitur RAR yang tidak didukung build ini. Unduh ulang, atau ekstrak di komputer Anda lalu unggah foldernya. Jika dilindungi kata sandi, masukkan kata sandinya di bawah.",
