err_rar_unsafe_entry: "RAR ini memuat jalur berkas yang mengarah ke luar folder tujuan, jadi ditolak demi keamanan. Arsipnya mungkin rusak.",
fs_download_zip_dialog_title: "Simpan “{name}” sebagai .zip",
fs_install_confirm_body_usb: "Ini menaruh paket ke penyimpanan internal (konsol tidak bisa memasang langsung dari USB), memasangnya, lalu menghapus salinan sementara. Berkas asli di drive Anda tidak disentuh.",
