about_disclaimer_title: "Penafian",
about_disclaimer_purpose: "ps5upload disediakan hanya untuk tujuan riset, edukasi, interoperabilitas, dan pengembangan homebrew. Aplikasi ini tidak berafiliasi dengan, tidak didukung oleh, dan tidak terhubung dengan Sony Interactive Entertainment Inc. “PlayStation” dan “PS5” adalah merek dagang Sony Interactive Entertainment Inc., yang digunakan di sini hanya untuk identifikasi.",
about_disclaimer_piracy: "Gunakan hanya dengan perangkat keras milik Anda sendiri dan konten yang Anda miliki secara sah. Aplikasi ini tidak boleh digunakan untuk menyalin, mendistribusikan, atau menjalankan perangkat lunak yang tidak berhak Anda gunakan.",
about_disclaimer_risk: "Perangkat lunak ini disediakan “apa adanya”, tanpa jaminan apa pun. Mengoperasikan konsol yang dimodifikasi dapat merusaknya secara permanen, menghancurkan data simpanan dan lisensi secara tak terpulihkan, serta membuat akun atau konsol Anda diblokir. Anda menggunakannya sepenuhnya atas risiko sendiri dan menerima tanggung jawab penuh atas akibatnya. Cadangkan semua yang tidak sanggup Anda kehilangan sebelum memulai.",
