"backport_verify_unpatched_body": "eboot-nya masih membawa versi SDK asli, jadi tidak bisa berjalan di firmware ini apa pun pustaka yang terpasang — set pustaka bukan masalahnya. Jalankan backport lagi; jika terus terjadi, patch SDK tidak berhasil diterapkan.",
