"backport_verifying": "Menjalankan dan mengamati — peluncuran yang gagal dicoba ulang, karena peluncuran cukup tidak andal sehingga satu kegagalan tidak membuktikan apa pun.",
"backport_verify_running": "Sedang berjalan — apakah sampai ke permainan?",
"backport_verify_running_body": "Game masih berjalan setelah satu menit ({threads} thread). Artinya tidak mogok saat memuat, tetapi belum tentu bisa dimainkan — lihat layar. Simpan jika berfungsi, atau batalkan dan coba set berikutnya.",
