"joberr.ava1_commit_exists": "Berkas sudah diunggah tetapi tidak dapat dipublikasikan karena tujuan sudah ada. Pilih Timpa untuk menggantinya, atau pilih tujuan lain.",
"joberr.ava1_cross_device": "Tujuan berada di drive yang berbeda dari area penampungan, sehingga PS5 tidak bisa memindahkan berkas. Pilih tujuan di drive yang sama atau unggah dulu ke drive internal.",
"joberr.ava1_wrong_console": "Perangkat di alamat ini bukan PS5 yang dipasangkan dengan aplikasi ini. Periksa alamatnya, atau pasangkan ulang dengan konsol ini.",
"joberr.ava1_no_identity": "Aplikasi ini belum memiliki identitas pemasangan. Pasangkan dengan PS5 dari layar Koneksi, lalu coba lagi.",
"joberr.zip_read_error": "Berkas .zip tidak dapat dibaca (berkas atau drive-nya mungkin hilang saat dibaca). Pastikan sumber masih terhubung, lalu klik Coba lagi.",
"joberr.ava1_zip_corrupt": "Berkas .zip ini tidak dapat dibaca: rusak atau tidak lengkap. Unduh atau buat ulang, lalu coba lagi.",
"joberr.ava1_7z_corrupt": "Berkas .7z ini tidak dapat dibaca: rusak atau tidak lengkap. Unduh atau buat ulang, lalu coba lagi.",
"joberr.ava1_7z_encrypted": "Berkas .7z ini terenkripsi dan tidak dapat di-stream. Ekstrak di komputer Anda dan unggah foldernya.",
"joberr.ava1_7z_unsafe_path": "Berkas .7z ini berisi jalur berkas yang tidak aman (keluar dari foldernya sendiri). Ekstrak di komputer Anda dan unggah foldernya.",
"joberr.tar_read_error": "Arsip tidak dapat dibaca (berkas atau drive-nya mungkin hilang saat dibaca). Pastikan sumber masih terhubung, lalu klik Coba lagi.",
"joberr.ava1_tar_corrupt": "Arsip ini tidak dapat dibaca: rusak atau tidak lengkap. Unduh atau buat ulang, lalu coba lagi.",
"joberr.ava1_tar_unsafe_path": "Arsip ini berisi jalur berkas yang tidak aman (keluar dari foldernya sendiri). Ekstrak di komputer Anda dan unggah foldernya.",
"joberr.ava1_tar_unsupported": "Arsip ini berisi sesuatu yang tidak dapat diekstrak oleh pengunggah (berkas sparse, dua nama yang hanya berbeda huruf besar-kecilnya, atau satu volume dari tar multi-volume). Ekstrak di komputer Anda dan unggah foldernya.",
"joberr.ava1_tar_memory": "Arsip ini dikompresi dengan jendela memori yang lebih besar (zstd --long) daripada yang diizinkan perangkat ini untuk mengekstrak. Unggah dari komputer dengan memori lebih besar, atau kompres ulang tanpa --long.",
"joberr.rar_password": "Berkas .rar ini memerlukan kata sandi, atau kata sandi yang diberikan salah. Masukkan kata sandi yang benar lalu coba lagi.",
"joberr.rar_corrupt": "Berkas .rar ini rusak, atau sebagian bagiannya hilang atau tidak berurutan. Pastikan semua bagian ada, lalu coba lagi.",
"joberr.ava1_copy_lost": "PS5 kehilangan jejak penyalinan ini (helper dimulai ulang atau koneksi terputus). Klik Coba lagi untuk memulainya dari awal.",
"joberr.ava1_copy_failed": "PS5 tidak dapat menyelesaikan penyalinan. Periksa ruang kosong dan pastikan sumber serta tujuan masih tersedia, lalu coba lagi.",
"joberr.ava1_local_io": "Komputer ini tidak dapat menulis berkas yang diunduh. Periksa izin dan ruang kosong folder tujuan, lalu coba lagi.",
"joberr.ava1_bad_manifest": "PS5 mengirim daftar berkas yang tidak dimengerti aplikasi ini. Perbarui helper dan aplikasi ke versi yang sama, lalu coba lagi.",
"joberr.helper_not_ava1": "Helper PS5 tidak berjalan. Kirim dari layar Koneksi, lalu coba lagi.",
"joberr.file_too_large": "File ini terlalu besar untuk format drive tujuan: FAT32 menampung paling banyak 4 GiB per file. Gunakan drive exFAT atau penyimpanan internal PS5.",
"joberr.source_missing": "Folder yang akan dikirim sudah tidak ada. Jika di drive eksternal atau share, sambungkan lagi, lalu coba lagi.",
"joberr.source_read_failed": "Sebuah file tidak dapat dibaca di komputer ini. Jika di drive eksternal atau share, pastikan masih tersambung, lalu coba lagi. Yang sudah sampai di PS5 tetap disimpan.",
"joberr.not_paired": "PS5 ini belum menerima aplikasi ini. Pasangkan keduanya (tombol Pasangkan…), lalu coba lagi.",
"joberr.helper_starting": "Helper PS5 masih dimulai. Tunggu beberapa detik, lalu coba lagi.",
"joberr.ava1_failed": "Helper PS5 sudah dimulai tetapi server transfernya tidak. Mulai ulang konsol, lalu coba lagi.",
"joberr.helper_not_running": "Tidak ada helper yang berjalan di PS5. Kirim dari layar Koneksi, lalu coba lagi.",
