volumes_store_pkg_copies: "Simpan salinan paket di sini",
volumes_pkg_copies_hint: "Fungsi pilihan ini: “Unggah & instal” lebih dulu menyalin file .pkg ke PS5, lalu menginstal dari salinan itu. Ini hanya menentukan drive mana yang menyimpan salinan tersebut. Ini tidak mengubah tempat game diinstal (PS5 menentukannya di pengaturan Penyimpanan miliknya), dan “Stream & instal” tidak menyimpan salinan sama sekali. Jika drive yang dipilih tidak terhubung, salinan masuk ke penyimpanan internal.",
saves_auto_folder_label: "Folder cadangan",
captures: "Tangkapan layar & klip",
captures_title: "Tangkapan",
"arcpkg.choose": "Pilih arsip…",
"arcpkg.help": "Untuk .zip, .7z, atau .rar yang berisi satu atau beberapa berkas .pkg di folder mana pun. Hanya paket yang diekstrak, langsung ke PS5 (tidak ada yang diekstrak di komputer ini), lalu dipasang satu per satu: game dasar dulu, lalu pembaruannya, lalu DLC. RAR multi-bagian (.part1.rar, .part2.rar…) didukung: pilih bagian pertama dan simpan sisanya di sebelahnya. Kata sandi diminta saat RAR membutuhkannya; ZIP dan 7z berkata sandi tidak didukung.",
"arcpkg.helpNoRar": "Untuk .zip atau .7z berisi satu atau lebih file .pkg, di folder mana pun. Hanya paket yang dibongkar, langsung ke PS5 (tidak ada yang diekstrak di perangkat ini), lalu diinstal satu per satu: game dasar sebelum pembaruannya, lalu DLC. File berkata sandi tidak didukung, dan .rar memerlukan aplikasi desktop.",
