"linkcard.fact.progress_ps5": "Progres terlihat di PS5",
"linkcard.forget": "Hapus dari daftar",
"linkcard.help2": "Tempel tautan unduhan langsung ke .pkg. Tidak ada yang disalin ke PS5 lebih dulu, jadi hanya perlu ruang untuk game terinstal, bukan juga untuk salinan.",
"linkcard.how": "Bagaimana cara mengambilnya?",
"linkcard.insecure": "Lewati pemeriksaan sertifikat",
"linkcard.insecure_hint": "Untuk server Anda sendiri atau situs yang sertifikatnya kedaluwarsa. Berlaku di sini karena komputer inilah yang membuat koneksi.",
"linkcard.install": "Pasang dari tautan",
"linkcard.mode.direct": "Biarkan PS5 mengunduhnya",
"linkcard.mode.direct_body": "PS5 mengambil tautan itu sendiri. PS5 harus dapat menjangkau tautan dan alamatnya harus pendek (yang panjang dipendekkan oleh aplikasi, dan aplikasi harus tetap terbuka).",
"linkcard.mode.download": "Unduh ke sini dulu, lalu pasang",
"linkcard.mode.download_body": "Komputer ini menyimpan seluruh paket, lalu memasangnya. Ini cara paling lambat, tetapi jika tautan kedaluwarsa atau terputus, Anda hanya perlu mengulang unduhan.",
"linkcard.mode.stream": "Stream melalui komputer ini",
