connection_payload_engine_unreachable: "Aplikasi tidak dapat menjangkau engine miliknya sendiri di komputer ini, jadi tidak tahu apakah helper sudah berjalan di PS5. Ini bukan masalah PS5: pemberitahuan di bagian atas jendela menjelaskan sebabnya dan dapat memulai ulang engine. Lalu tekan Kirim helper lagi. ({error})",
