sendpayload_probe_invalid_ext: "Payload harus berupa file .elf, .bin, .js, .lua, atau .jar.",
sendpayload_probe_no_signature: "Tanda tangan PS5Upload tidak ditemukan — gunakan hanya jika kamu memercayai payload ini.",
sendpayload_probe_ok: "File payload tampak baik.",
sendpayload_probe_read_error: "Tidak dapat membaca file ini ({error}). Pastikan file masih ada dan bisa dibuka, lalu pilih lagi.",
sendpayload_probe_too_small: "File ini kosong, jadi tidak ada yang bisa dikirim.",
servers_subtitle: "NAS dan servermu (SMB, FTP, FTPS, SFTP/WebDAV). Di mana pun kamu menelusuri game atau file, pilih dari daftar ini dengan ▾ di samping Telusuri.",
settings_artwork_cache_explain_v2: "Sampul game disimpan di tempat engine berjalan (komputer ini, atau server untuk versi web) sehingga langsung dimuat alih-alih dibaca dari PS5 setiap kali. Sampul diperbarui otomatis, dan dihapus untuk sebuah konsol saat kamu memasang atau mencopot game di sana.",
settings_backup_downloaded: "{name} diunduh",
settings_backup_no_pairing: "Pemasangan Remote Play dan kunci Wake tidak ada dalam file ini. Di perangkat baru, pasangkan konsol lagi.",
settings_backup_hint_v2: "Gabungkan tema, daftar PS5, riwayat notifikasi, log aktivitas, dan preferensi lain ke satu file JSON, untuk dipulihkan setelah menghapus penyimpanan aplikasi atau di mesin lain. Pemasangan konsol, Koleksi, kata sandi server tersimpan, dan pustaka backport tidak disertakan.",
settings_backup_restored: "{count} pengaturan dipulihkan. Mulai ulang aplikasi agar semua perubahan berlaku.",
settings_backup_saved: "Disimpan ke {path}",
settings_card_console_rest: "Mode istirahat",
settings_card_console_connect: "Menghubungkan",
auto_bringup_label: "Siapkan otomatis",
bringup_auto_hint_short: "Menjalankan ini sendiri saat loader PS5 aktif dan helper tidak, sekitar 90 detik setelah loader muncul. Sekali setiap kali konsol dinyalakan.",
settings_card_install_fallback: "Saat PS5 tidak dapat mengambil paket",
settings_card_system_files: "File sistem",
settings_file_hint_v2: "Preferensi utama (tema, bahasa, engine, jalur simpan, bawaan unggah, aksesibilitas, sidebar) dicerminkan ke file JSON ini. Kamu bisa mengeditnya secara manual; perubahan berlaku saat aplikasi dibuka berikutnya. File ini tidak memuat semuanya: gunakan Cadangkan / pulihkan untuk membawa semua preferensimu.",
settings_group_console: "Konsol",
settings_group_fakelibs: "Backport",
settings_group_files_saves: "Berkas & data simpan",
settings_group_installs: "Pemasangan",
settings_schedule_label_placeholder_v2: "Label (mis. cadangkan data simpan)",
settings_updates_browser_note: "Halaman web ini disajikan oleh engine ps5upload dan diperbarui bersamanya: tarik image Docker baru (atau perbarui engine di servermu) lalu mulai ulang.",
"show_file_list_hint_v2": "Tampilkan daftar file yang sedang diunggah di bawah bilah kemajuan. Matikan jika daftarnya terasa ramai pada folder berisi ribuan file — kemajuan total, kecepatan, dan perkiraan waktu tetap terlihat.",
show_file_list_v2: "Tampilkan daftar file saat mengunggah",
stats_description_v2: "Total dari operasi yang ditampilkan untuk konsol ini. Aplikasi menyimpan {count} terakhir, jadi yang lebih lama tidak dihitung. Dihitung dari riwayat lokal; tidak ada yang keluar dari mesinmu.",
update_idle_v2: "Belum diperiksa. Dengan pemeriksaan otomatis aktif, aplikasi memeriksa di latar belakang saat dibuka, paling sering sekali sehari.",
upload_auto_resume_hint_browser: "Jika unggahan terputus di tengah transfer, lanjutkan dari titik terakhir setelah helper PS5 menjawab lagi, dengan mencoba ulang beberapa kali sebelum menyerah. Halaman ini tidak dapat mengirim ulang helper itu sendiri: jika PS5 dimulai ulang, kirim lagi helper terlebih dahulu. Masalah fatal seperti PS5 kehabisan ruang tetap langsung menghentikan unggahan. Aktif secara bawaan.",
settings_verify_writes: "Periksa file di PS5 setelah ditulis",
settings_verify_writes_hint: "Setelah setiap file besar disimpan, PS5 membacanya kembali dari drive-nya dan mencocokkannya dengan yang dikirim. File yang tidak cocok dikirim ulang. Menambah sedikit waktu di akhir file yang sangat besar. Perlu helper versi terbaru. Aktif secara bawaan.",
upload_wake_for_uploads: "Bangunkan PS5 untuk unggahan yang menunggu",
