"minion_lan_hint": "Nonaktif: hanya browser PS5 sendiri yang membukanya. Aktif: ponsel, tablet, atau komputer di jaringan yang sama juga dapat membukanya, sehingga siapa pun di jaringan itu bisa. Aktifkan hanya di rumah.",
"minion_open_here": "Buka di sini",
"minion_remove_note": "Hapus akan menonaktifkan Minion dan menghapus yang disimpannya di PS5: favorit dan folder terbaru di Berkas, daftar game tersimpan, dan log kontroler. Folder jaringan, cheat, dan cadangan tetap ada; aplikasi PC juga memakainya.",
