"minion_remove_title": "Hapus PS5Upload Minion?",
"minion_remove_confirm": "Ubin layar beranda dan halamannya hilang, dan file miliknya di PS5 dihapus. Helper akan menjaganya tetap nonaktif mulai sekarang. Anda dapat mengaktifkannya lagi di sini kapan saja.",
