"fs_drag_hint_move": "Seret file dan folder keluar dari jendela untuk menyalinnya ke komputer ini, atau seret ke dalam untuk menyalinnya ke sini. Tahan Alt (⌥ Option di Mac) saat menyeret untuk memindahkannya ke folder di sini.",
