"installed_uninstall_no_copy": "Koleksi Anda di komputer ini tidak memiliki salinan game ini: simpan paketnya di suatu tempat sebelum menghapus instalasinya.",
"connection_send_payload_moved": "Ingin mengirim payload lain (kstuff, etaHEN, .elf apa pun)? Itu ada di Payload → Kirim payload. Layar ini hanya mengirim helper PS5Upload.",
"connection_send_payload_open": "Buka Kirim payload",
"upload_elf_title": "Ini payload (.elf), bukan game",
"upload_elf_body": "Mengunggahnya hanya menyalin file. ShadowMount+ mengambil folder game (berisi eboot.bin dan sce_sys) dan image game, tidak pernah .elf, jadi tidak akan muncul di layar beranda. Untuk menjalankannya, kirim ke loader konsol. Yang perlu diunggah adalah aplikasi homebrew yang berbentuk image .ffpkg atau .exfat, atau folder berisi eboot.bin.",
"netdoctor.hint.below_test": "Unggahan ini berjalan pada {speed}, jauh di bawah {expected} yang diukur uji kecepatan.",
"netdoctor.hint.runs_at": "Unggahan ini berjalan pada {speed}.",
"netdoctor.hint.cause_source": "Yang menahannya adalah membaca file di komputer ini, bukan jaringan: drive USB atau hard disk, folder jaringan (NAS) atau membongkar arsip lebih lambat dari koneksi. Menyalin game ke SSD internal terlebih dahulu, atau mengunggah file arsip setelah dibongkar, memberi kecepatan penuh.",
"netdoctor.hint.cause_disk": "Yang menahannya adalah drive PS5, bukan jaringan: drive USB eksternal, drive yang hampir penuh, atau ribuan file kecil (masing-masing butuh waktu sendiri) menulis lebih lambat dari yang dikirim koneksi. Image game (.ffpkg atau .exfat) dikirim sebagai satu file.",
"netdoctor.hint.cause_workers": "PS5 masih menulis apa yang diterimanya, bukan menunggu jaringan. Dengan banyak file kecil, masing-masing butuh waktu sendiri; image game (.ffpkg atau .exfat) dikirim sebagai satu file.",
"netdoctor.hint.cause_cap": "Yang menahannya adalah batas kecepatan unggah (sekitar {cap} MiB/s, di layar ini dan di Pengaturan). Setel ke 0 untuk menghapusnya.",
"profile.np.confirm_body_v2": "np-fake-signin menulis berkas dan pengaturan masuk PlayStation Network untuk {user} di PS5. Tidak ada yang dikirim ke Sony. Mulai ulang PS5 setelahnya.",
"profile.np.side_effect": "Efek samping yang diketahui: setelahnya beberapa konsol meminta \"Nonaktifkan Sementara Pembatasan Konsol PS5\" sebelum game apa pun terbuka, dan Pengaturan > Pengguna dan Akun > Lainnya > Keluar bisa tetap berwarna abu-abu. Aplikasi lebih dulu menyimpan salinan semua yang diubah np-fake-signin di PS5, jadi Batalkan masuk di sini mengembalikannya.",
"profile.np.backing_up": "Menyimpan salinan pengaturan akun saat ini di PS5…",
"profile.np.backup_failed": "PS5 tidak dapat menyimpan salinan pengaturan akun, jadi np-fake-signin tidak dijalankan. Ganti helper dengan versi aplikasi ini lalu coba lagi. ({error})",
"profile.np.step_restart_v2": "Mulai ulang PS5. Untuk membatalkannya nanti, tekan Batalkan masuk di sini lalu mulai ulang lagi.",
"profile.np.undo": "Batalkan masuk",
"profile.np.undo_hint": "Salinan pengaturan akun ini dari sebelum masuk disimpan di PS5; ini mengembalikannya.",
"profile.np.undo_confirm_title": "Batalkan masuk?",
"profile.np.undo_confirm_body": "Mengembalikan pengaturan dan berkas {user} seperti sebelum np-fake-signin dijalankan. Mulai ulang PS5 setelahnya. Fitur yang butuh akun yang sudah masuk, termasuk Remote Play, mungkin tidak terbuka sampai Anda masuk lagi.",
"profile.np.undoing": "Mengembalikan pengaturan…",
"profile.np.undone": "Dikembalikan ({count} pengaturan dan berkas). Mulai ulang PS5 untuk menyelesaikan.",
"profile.np.no_backup": "Akun ini membawa pengaturan templat np-fake-signin (tanggal lahir 1983-04-12, penanda dewasa luring mati), dan tidak ada salinan dari sebelumnya di PS5 ini, jadi aplikasi tidak dapat membatalkannya. Jika PS5 kini meminta menonaktifkan sementara pembatasan konsol sebelum game terbuka: Pengaturan > Keluarga dan Kontrol Orang Tua > Pembatasan Konsol PS5 (kode sandi 0000 kecuali Anda mengubahnya), lalu cabut pembatasannya di sana.",
"linkdl.lz4_title": "Tautan ini dikompresi dengan LZ4",
"linkdl.image_title": "Tautan ini adalah image game",
"linkdl.lz4_help": "ps5upload dapat mengekstraknya sambil mengunduh, sehingga PS5 menerima file yang sudah diekstrak. Tidak ada yang disimpan di komputer ini, dan PS5 hanya butuh ruang untuk file yang sudah diekstrak.",
"linkdl.lz4_unpack": "Ekstrak di jalan",
"linkdl.lz4_unpack_hint": "Mati: file .lz4 disimpan di PS5 apa adanya.",
"linkdl.image_hint": "Image game {kind}. ShadowMount+ memasangnya apa adanya dari folder yang dipindainya, seperti homebrew di sebuah drive. File baru muncul di sana setelah lengkap.",
"pm_add_failed": "Tidak dapat menyimpan {name} di Payload Manager",
"pm_catalogue_match": "Katalog: {name}",
"pm_replace_tooltip": "Payload Manager tidak menyimpan versi untuk payload yang ditambahkan manual, jadi ps5upload tidak bisa tahu apakah yang ini lebih lama. Mengganti akan menyimpan rilis katalog di tempatnya dan mempertahankan posisinya di daftar boot; setelah itu, pembaruan ditawarkan di sini.",
"pm_replace_with": "Ganti dengan {tag}",
"pm_add_header": "Tambahkan ke Payload Manager",
"pm_add_local": "Dari komputer ini…",
"pm_add_catalogue_label": "Payload katalog yang diunduh",
"pm_add_catalogue_pick": "Payload katalog…",
"pm_add_hint": "Payload Manager menyimpan file di PS5, menjalankannya dari sini atau saat boot, dan menampilkannya di menunya sendiri. Payload yang disimpan dari katalog ditawarkan di sini saat katalog punya rilis yang lebih baru.",
"payloads_title": "Payload",
"payloads_tab_running": "Berjalan",
"payloads_ports_heading": "Port yang dipakai",
"payloads_description_running": "Program yang sedang berjalan di PS5, dan port yang dipakai beserta yang biasanya mendengarkan di masing-masing. Anda bisa menghentikan atau memulai ulang program; hati-hati dengan proses sistem, menghentikan yang salah bisa membuat konsol macet.",
"accounts_title": "Akun",
"accounts_users_title": "Pengguna",
"ps4move_title": "Pindahkan data simpanan dari PS4",
"ps4move_badge": "Eksperimental",
"ps4move_experimental": "Eksperimental: menaruh simpanan format PS4 di PS5 tidak selalu berhasil, dan game mungkin tidak memuatnya. Coba satu game dulu; simpanan PS5-nya disimpan, jadi bisa dikembalikan dari cadangan game.",
"ps4move_safety": "PS4 hanya dibaca, tidak pernah diubah. Data simpanannya disalin dulu ke komputer ini. Di PS5 hanya game yang kamu pilih yang disentuh, simpanan masing-masing dicadangkan sebelum diganti, dan tidak ada yang lain (pengguna, file sistem, trofi) yang berubah.",
"ps4move_need_dir": "Pilih dulu folder di Cadangan otomatis di atas: simpanan PS4 disimpan di sana, begitu juga setiap simpanan PS5 sebelum diganti.",
"ps4move_step1": "1. PS4",
"ps4move_step1_hint": "Di PS4 yang sudah di-jailbreak, nyalakan server FTP-nya (milik GoldHEN, biasanya port 2121), lalu masukkan alamatnya.",
"ps4move_address": "Alamat PS4",
