"fpkg.image.zstd_body": "Mengemas semua kecuali file sistem game ke dalam paket zstd, ditulis langsung ke image tanpa salinan sementara. Image mendapat ampr-emu-ng dari quer3q sebagai emulatornya, diperiksa dengan digest yang dipublikasikan sebelum dipakai. Game yang sudah dalam paket LZ4 dialihkan. Matikan update_emulators di ShadowMount+, atau emulatornya bisa ditukar dengan yang tidak bisa membacanya.",
"fpkg.image.zstd_level": "Tingkat kompresi",
"fpkg.image.zstd_runtime": "Runtime paket",
"fpkg.image.zstd_runtime_latest": "Rilis terbaru (bawaan)",
"fpkg.image.zstd_runtime_pinned": "Teruji {version}",
"fpkg.image.zstd_runtime_body": "“Terbaru” memakai rilis ampr-emu-ng terbaru di GitHub hanya jika cocok dengan SHA-256 yang dipublikasikan GitHub untuknya; jika tidak, atau saat offline, versi teruji {version} yang dipakai. “Teruji” selalu memakai {version}.",
"fpkg.folder.zstd_body": "Menulis game sebagai folder biasa, semua kecuali file sistemnya dalam paket zstd, dengan ampr-emu-ng dari quer3q sebagai fakelib/libSceAmpr.sprx. Sumbernya juga bisa folder game. Paket LZ4 tidak ditawarkan di sini: hanya masuk ke image .exfat. Matikan update_emulators di ShadowMount+, atau emulatornya bisa ditukar dengan yang tidak bisa membacanya.",
"ampr_emu_add_hint": "Game ini membaca berkasnya lewat AMPR dan tidak punya emulator. Beberapa game seperti ini tidak mau mulai dari image tanpanya, yang lain berjalan baik. Menambahkan ampr_emu 0.4.2.1 milik drakmor, diunduh sekali dan dicek dengan digest yang dikenal. Image tidak berubah: emulator masuk ke folder backport ShadowMount+.",
"ampr_emu_done_backport": "Ditambahkan sebagai backport ShadowMount+ di {folder}. Image tidak berubah. Mulai game untuk mencobanya.",
"ampr_emu_done_folder": "Ditambahkan ke folder game, {folder}. Mulai game untuk mencobanya.",
"fpkg.fake_sign_note": "{count} executable biasa (tanpa tanda tangan) di game ini ditandatangani palsu saat dikonversi, kalau tidak game tidak akan mulai. Sumbernya tidak berubah.",
"fpkg.image.ampr_emu": "Tambahkan emulator AMPR",
"fpkg.image.ampr_emu_body": "Game ini membaca berkasnya lewat AMPR dan tidak punya emulator. Beberapa game seperti ini tidak mau mulai dari image tanpanya, yang lain berjalan baik. Menambahkan ampr_emu 0.4.2.1 milik drakmor sebagai fakelib/libSceAmpr.sprx, diunduh sekali dari rilis GitHub dan dicek dengan digest yang dikenal.",
"fpkg.image.lz4_placement_note": "Simpan image yang dikemas di penyimpanan internal konsol: ada laporan satu image macet di layar hitam dari USB. Matikan update_emulators di ShadowMount+, atau emulatornya bisa diganti dengan yang tidak bisa membaca paket.",
