"rp_err_rp_off": "Remote Play dimatikan di PS5. Di konsol, buka Pengaturan › Sistem › Remote Play lalu nyalakan Aktifkan Remote Play (jika sudah menyala, matikan lalu nyalakan lagi), kemudian tekan Mulai. Abu-abu? Akun pengguna PS5 harus diaktifkan, dan PS5 yang dialihkan ke lingkungan NP sp-int membuatnya tetap mati: kembalikan ke np.",
"rp_err_refused": "PS5 menolak memulai Remote Play. Di konsol, periksa Pengaturan › Sistem › Remote Play › Aktifkan Remote Play (matikan lalu nyalakan lagi), tekan Izinkan di Main › Siapkan, atau pasangkan ulang. Kode di bawah menunjukkan penolakan yang mana. Masih ditolak? Mulai ulang PS5: konsol yang lama menyala bisa menolak sampai dimulai ulang.",
