"rp_picture_here": "Gambar di perangkat ini",
"rp_picture_here_hint": "Saat mati, stream baru dimulai tanpa gambar, suara, atau kontroler di sini, sehingga menghemat CPU dan baterai perangkat ini. Teman di Play Together dan Go live tetap mendapat stream, dan Anda bisa menyalakannya dari stream kapan saja.",
