"send_title_v2": "Unggah & Instal",
"collection.send_many_body_v2": "Setiap PS5 mendapat apa yang belum dimilikinya: paket game, atau folder, image, atau arsipnya, plus pembaruan dan DLC yang lebih baru untuk game yang sudah ada. Paket di-stream dari komputer ini; sisanya diunggah ke drive yang diatur di Unggah & Instal, di folder homebrew.",
"first_run_step4_body_v3": "Colokkan flashdisk USB berisi image game .ffpkg ke PS5 dan ShadowMount+ akan me-mount-nya otomatis — semuanya muncul di Gim. Untuk mengirim file lain atau memasang paket .pkg, gunakan Unggah & Instal.",
"first_run_go_upload_v2": "Buka Unggah & Instal",
"fpkg.aboutFake_v2": "Hasilnya adalah paket palsu, jadi konsol perlu dukungan paket palsu dimuat sebelum mau memasangnya: kstuff (versi dengan dukungan paket palsu PS5), a53_ppr_install_fast.elf, dan shadowmountplus.elf, dengan urutan itu. Unggah & Instal menyebutkan hal yang sama di samping tombol instalnya.",
"fpkg.openUpload_v2": "Buka Unggah & Instal",
"netdoctor.speed_cap.on.fix_v2": "Hapus batasnya di Unggah & Instal jika tidak diperlukan.",
"payloads_fpkg_ppr_note_v2": "Memasang paket palsu juga membutuhkan a53_ppr_install_fast.elf, yang tidak ada di daftar ini: tidak ada unduhan yang dirilis, dan dibuat dari kode sumber di GitHub. Unggah & Instal mencantumkan semua yang dibutuhkan paket palsu, secara berurutan.",
"fs_extract_next_pkgs_v2": "Berisi {n} paket: instal dari Unggah & Instal, atau dari barisnya di sini.",
"game_hub_no_addons_v2": "Tidak ada paket DLC yang disiapkan untuk judul ini. Kirim satu dari Unggah & Instal.",
"game_hub_open_install_v2": "Buka Unggah & Instal",
"bandwidth_cap_off_hint_v3": "Tanpa batas. Atur batas jika unggahan memenuhi Wi-Fi/LAN dan membuat perangkat lain lambat. Berlaku untuk setiap unggahan, dari Unggah & Instal, antrean, dan Berkas, mulai unggahan berikutnya.",
"game_hub_no_updates_v2": "Tidak ada paket pembaruan yang disiapkan untuk judul ini. Kirim satu dari Unggah & Instal.",
"pkglib.fpkgsupport.firmware": "Paket palsu PS5 (PS5 FPKG) belum didukung di firmware setelah 11.60: paketnya terpasang, tetapi game tidak mau dimulai. Paket palsu PS4 tidak bermasalah.",
"upload_drop_here3": "Letakkan atau pilih paket, game, image disk, arsip, atau file apa pun",
"upload_pick_here_mobile3": "Pilih paket, game, image disk, arsip, atau file apa pun",
"upload_drop_kind_pkg": "Paket (.pkg, .fpkg): diinstal sebagai game, pembaruan, atau DLC, di-stream dari sini atau diunggah dulu.",
"upload_drop_kind_game": "Folder game dan dump game: disalin ke PS5; bisa ditaruh di layar beranda.",
"upload_drop_kind_image": "Image disk (.exfat, .ffpkg, .ffpfs, .ffpfsc): disalin ke PS5; bisa di-mount.",
"upload_drop_kind_archive": "Arsip (.zip, .7z, .rar, .tar, .tar.zst, .tar.gz, .tar.xz, .tar.bz2, .zst): diekstrak ke PS5, atau dikirim apa adanya — Anda yang memilih.",
"upload_drop_kind_other": "File atau folder lain: disalin apa adanya.",
"upload_other_ways": "Atau instal paket:",
"queue_stream_fail_hint": "Stream & instal membuat PS5 mengambil paket dari komputer ini. Jika terus gagal, izinkan ps5upload melewati firewall komputer ini di jaringan lokal agar PS5 bisa menjangkaunya, atau gunakan Coba lagi lewat unggah, yang menyalin paket ke PS5 terlebih dahulu lalu memasangnya.",
"err_install_enoent_generic_v2": "Installer Sony tidak dapat membuka file yang diperlukannya selama pemasangan (kesalahan kernel 0x80020002 = ENOENT). Jika ini pkg DLC, base game belum terpasang — pasang base terlebih dahulu. Jika tidak, paket yang disiapkan mungkin terhapus antara unggah dan pasang; coba ulang pemasangan sekali. Jika terus gagal, pasang dengan Stream & instal di Unggah & Instal, yang mengirim paket langsung dari komputer ini alih-alih menyalinnya ke konsol terlebih dahulu.",
"err_display_crashed": "Tampilan aplikasi mengalami kesalahan saat ini berjalan (React #185) dan berhenti mengikuti transfer, yang mungkin tetap selesai. Periksa PS5, atau tekan Coba lagi. Laporan bug sekarang membantu kami memperbaikinya.",
"upload_convert_first": "Konversi dulu",
"batch_convert_first_hint": "Buka game, folder, dan image yang dicentang di Bengkel, untuk membuat paket, image, atau folder darinya terlebih dahulu",
"add_sources_pick_folders": "Pilih satu atau beberapa folder",
"add_sources_pick_files": "Pilih satu atau beberapa file",
"workshop_add_hint": "Pilih satu game untuk memeriksanya di sini. Beberapa game, atau folder berisi game, masuk ke antrean dan dibuat satu per satu.",
"cq_title_v2": "⑤ Antrean",
"cq_about": "Dibuat satu per satu di komputer ini, masing-masing sesuai pengaturan ②, ③, dan ④ saat ditambahkan. Tambahkan lagi di ①, bahkan saat antrean berjalan; ubah game yang menunggu dengan tombol opsinya.",
"cq_then_send": "Game yang diatur untuk diinstal atau diunggah akan masuk ke antrean {send} setelah selesai dibuat.",
"cq_open_send": "Buka {send}",
"backup_alike_toggle": "{count} salinan serupa sejak {since}. Tampilkan masing-masing untuk memulihkan yang lebih lama.",
"add_sources_no_picker": "Build ini tidak dapat menelusuri komputer ini — ketik jalur yang dapat dilihat engine.",
"collection.empty_body_v2": "Paket, folder game, image game, dan arsip di dalamnya ditemukan dan dikelompokkan per game. Tidak ada yang diubah di folder. Folder di perangkat ini, drive eksternal, atau folder di NAS atau server (SMB, FTP, SFTP, WebDAV) bisa dipakai.",
"collection.add_nas_folder": "Dari NAS atau server",
"browse_this_device": "Perangkat ini…",
"browse_this_device_hint": "Membaca dari perangkat tempat browser ini berjalan. Disalin dua kali, ke server lalu ke PS5: lebih lambat, dan server butuh ruang kosong untuk salinannya.",
"browse_on_server": "Di server…",
"browse_on_server_hint": "Membaca dari {host}, komputer tempat engine berjalan. Paling cepat: langsung ke PS5.",
"browse_choose_source": "Pilih dari mana membaca",
"queue_added_waits_for_start": "Ditambahkan ke antrean — tekan “Mulai antrean” untuk menjalankannya",
"queue_added_waits_for_start_body": "“Mulai antrean saat Anda menambahkan sesuatu” nonaktif, jadi tidak ada yang dimulai sampai Anda menekan “Mulai antrean”.",
"queue_auto_start": "Mulai antrean saat Anda menambahkan sesuatu",
"queue_auto_start_tooltip": "Aktif: “Instal”, “Unggah sekarang”, dan “Kirim” memulai seluruh antrean konsol ini, berurutan. Nonaktif: hanya menambahkan ke antrean, dan tidak ada yang berjalan sampai Anda menekan “Mulai antrean”.",
"queue_auto_start_hint": "Aktif: “Instal”, “Unggah sekarang”, dan “Kirim” memulai seluruh antrean konsol, berurutan — bukan hanya yang baru Anda tambahkan. Nonaktif: hanya menambahkan ke antrean, dan tidak ada yang berjalan sampai Anda menekan “Mulai antrean”. Aktif secara bawaan.",
"queue_start_rest_tooltip": "Hanya item yang Anda mulai yang sedang berjalan. Ini juga menjalankan semua yang menunggu, sesuai urutan antrean.",
"queue_start_v2": "Mulai antrean",
"queue_stop_v2": "Hentikan antrean",
"upload_starts_queue": "Memulai antrean: yang sudah menunggu berjalan lebih dulu, berurutan",
