helper_copy_place_autoloader: "autoloader",
helper_boot_label: "Muat helper PS5Upload saat boot",
helper_boot_hint: "Payload Manager menjalankan helper setelah semua yang ada di atasnya dalam daftar boot, sehingga Minion dan aplikasi ini berfungsi setelah restart tanpa PC. Setiap kali tersambung, aplikasi ini memperbarui salinan itu ke helper miliknya dan menyimpan yang sebelumnya; jika salinan baru tidak berjalan setelah restart, yang sebelumnya dikembalikan.",
helper_boot_list_off: "Daftar boot Payload Manager dimatikan di atas, jadi tidak ada yang berjalan saat boot sampai Anda menyalakannya.",
helper_boot_list_off_title: "Daftar boot Payload Manager mati",
