helper_boot_not_listed: "Helper sudah disimpan tetapi tidak ada di daftar boot Payload Manager. Aplikasi ini memasukkannya kembali saat terhubung berikutnya.",
helper_boot_bad_version: "Helper {version} tidak berjalan saat boot di PS5 ini, jadi salinan sebelumnya dikembalikan. Versi aplikasi yang lebih baru akan mencoba lagi.",
helper_boot_needs_pm: "Memuat helper PS5Upload saat boot memerlukan Payload Manager: dialah yang menjalankan helper saat PS5 menyala.",
helper_boot_failed: "Tidak dapat mengubah apakah helper dimuat saat boot",
helper_boot_on_title: "Helper kini dimuat saat boot",
helper_boot_restored_title: "Helper tidak berjalan saat boot",
helper_boot_restored_body: "PS5 dimulai ulang tetapi helper {version} yang disimpan Payload Manager tidak berjalan, jadi aplikasi ini mengirim satu. Salinan sebelumnya kembali ada di Payload Manager dan berjalan pada restart berikutnya. Aplikasi ini tidak akan menyimpan {version} di sana lagi.",
helper_copies_updated_title: "Helper diperbarui",
helper_copies_updated_body: "PS5 Anda akan menjalankan helper {version} saat dinyalakan ulang berikutnya.",
helper_copies_failed_title: "Tidak dapat memperbarui helper yang dijalankan PS5 saat boot",
helper_copies_failed_body: "Masih helper lama: {list}. PS5 menjalankannya lagi setiap restart. Untuk memperbaikinya manual, unduh ps5upload.elf {version} dari halaman rilis dan salin menimpa file itu (layar Files, FTP, atau drive USB), atau unggah lagi di Payload Manager dengan nama yang sama. ({error})",
