mcp_tab_api: "API",
mcp_phone_title: "Atur ini di komputer",
mcp_phone_body: "Mesin di aplikasi ponsel ini hanya untuk aplikasi itu sendiri. Untuk memakai agen atau skrip, jalankan di komputer dengan PS5Upload terbuka, atau dengan mesin Docker.",
mcp_other_computer_title: "Mesin ini ada di komputer lain",
mcp_other_computer_body: "Agen di komputer itu bisa mengikuti langkah ini dengan alamat 127.0.0.1 miliknya. Agen di tempat lain juga perlu alamatnya ada di pengaturan PS5UPLOAD_ALLOW_IP mesin.",
mcp_intro: "MCP memungkinkan agen AI mengendalikan PS5 kamu dengan alat yang dipahaminya: mengirim file, memasang game, memeriksa suhu, dan lainnya. Tambahkan sekali, lalu tinggal minta.",
mcp_address: "Alamat MCP",
mcp_agents_title: "Tambahkan ke agen kamu",
mcp_check_again: "Periksa lagi",
mcp_after_adding: "Mulai sesi baru di agen untuk memuatnya. Biarkan PS5Upload tetap terbuka selama agen bekerja: server MCP adalah bagian dari mesinnya.",
mcp_update_title: "Menjaganya tetap terbaru",
mcp_update_app: "Saat PS5Upload diperbarui, tidak ada yang perlu dilakukan di sini. Agen mendapat alatnya dari mesin, jadi alat baru muncul saat Anda memulai sesi berikutnya. Sesi yang sudah terbuka tetap memakai daftar lama.",
mcp_update_address: "Jika alamat mesin berubah, aplikasi memberi tahu saat dimulai, dan kartu agen di sini menampilkan Perbarui. Satu klik memperbaikinya.",
mcp_update_by_hand: "Aplikasi tidak dapat melihat Gemini CLI, Cursor, Claude Desktop, atau skrip Anda sendiri. Jika alamat di sini berubah, atau salah satunya berhenti terhubung setelah pembaruan, salin lagi penyiapannya dari Agen dan aplikasi lain.",
mcp_update_version: "Mesin ini versi {version}. Untuk melihat apa yang terhubung ke agen, tanyakan versi mesin PS5Upload kepadanya.",
mcp_bridge_body: "Ini menjalankan program jembatan mesin, bukan memakai alamat ini. Itu juga berfungsi. Perbarui mengalihkannya ke alamat.",
mcp_stale_toast: "Sebuah agen masih memakai alamat lama mesin, jadi tidak bisa terhubung. Perbarui di MCP & API.",
mcp_stale_open: "Buka",
mcp_try_title: "Lalu coba tanyakan",
mcp_try_status: "Seberapa panas PS5 saya sekarang?",
mcp_try_space: "Apa yang paling banyak memakai ruang di PS5 saya?",
mcp_try_install: "Pasang paket ini di PS5 saya dan beri tahu saya kalau sudah selesai.",
mcp_safety_title: "Agen bisa melakukan apa pun yang kamu bisa",
mcp_safety_body: "Tidak ada kata sandi, dan agen bisa menghapus file di konsol kamu. Biarkan alat yang mengubah sesuatu tetap di \"ask\", dan baca setiap perintah konsol sebelum mengizinkannya.",
mcp_safety_read_only: "Agar agen hanya bisa melihat, atur ini di lingkungan mesin lalu mulai ulang mesin:",
mcp_access_label: "Agen boleh mengubah sesuatu",
mcp_access_hint: "Mati: agen hanya bisa melihat, misalnya mendaftar file, membaca status, dan mengikuti transfer. Tidak ada yang berubah.",
