cb_step_restart_body: "Safe Mode bisa terbuka dengan hanya opsi terakhir, Reset PS5 (Instal Ulang Perangkat Lunak Sistem). Menurut pengguna, memilih Mulai Ulang PS5 lalu masuk Safe Mode sekali lagi mengembalikan opsi lainnya. Coba ini sebelum yang lain.",
cb_step_repair: "Perbaiki Penyimpanan Konsol",
