cb_step_rebuild: "Hapus Cache dan Bangun Ulang Database",
cb_step_rebuild_body: "Membangun ulang daftar konten konsol. Game dan data simpanan Anda tetap ada. Di konsol yang sudah di-jailbreak, game dan aplikasi yang didaftarkan manual mungkin perlu didaftarkan lagi. Sebagian orang melaporkan ini sudah cukup, tapi belum kami konfirmasi.",
