cb_step_reinstall_body: "Pilihan terakhir: ini juga menghapus perangkat lunak sistem dan butuh file instal ulang di drive USB. Situs Sony hanya menyediakan versi terbaru, jadi memakai filenya memperbarui firmware dan bisa mengakhiri jailbreak Anda.",
