"cw_tn_sub": "Main di PS5 ini dari mana saja lewat jaringan Tailscale Anda. Lewat jalur ini hanya Remote Play dan PS5Upload yang bisa menjangkaunya. Anda juga bisa menyiapkannya dari aplikasi PS5Upload: Koneksi › Tailscale untuk PS5 ini.",
