"settings_ps5_open_connection": "Buka Koneksi",
"settings_ps5_picker": "PS5",
"settings_ps5_picker_hint": "Pengaturan ini hanya milik PS5 ini. Setiap konsol Anda punya pengaturannya sendiri, dan pengaturan itu ikut ke perangkat Anda yang lain.",
"auto_bringup_hint_ps5": "Saat loader PS5 ini (elfldr, port 9021) aktif dan helper tidak berjalan, aplikasi menjalankan Penyiapan cepat sendiri: playlist penyiapan PS5 ini jika sudah diatur, lalu helper, lalu playlist auto-loader Anda. Sekali setiap kali PS5 ini dinyalakan; setelah mode istirahat hanya helper yang dikirim ulang. Aplikasi menunggu sekitar 90 detik setelah loader muncul, agar autoloader konsol sendiri selesai lebih dulu. Mati secara bawaan.",
"bringup_playlist_label_ps5": "Playlist penyiapan untuk PS5 ini (kernel R/W, SMP)",
"bringup_playlist_hint_ps5": "Dijalankan sebelum helper saat Penyiapan cepat. Payload bergantung pada firmware, jadi setiap PS5 punya playlist sendiri. Buat playlist di Payload.",
"upload_auto_redeploy_on_wake_hint_ps5": "Saat helper PS5 ini offline (mode istirahat, ganti Wi-Fi, atau payload crash), terus coba mengirimnya lagi di latar belakang, agar helper, ambang kipas PS5 ini, dan port unggah kembali sendiri begitu PS5 bisa dijangkau lagi. Aktif secara bawaan.",
"keep_ps5_awake_mode_hint_ps5": "Mengatur ulang timer standby otomatis PS5 ini agar tidak masuk mode istirahat. “Saat mengunggah dan memasang” melindungi unggahan panjang (penyebab umum unggahan gagal; bawaan). “Selalu saat terhubung” menjaga PS5 ini tidak masuk mode istirahat selama helper-nya berjalan dan aplikasi terbuka. Menidurkan PS5 sendiri tetap bisa di semua mode.",
"upload_rest_after_hint_ps5": "Ketika antrean unggah PS5 ini selesai, minta PS5 masuk mode istirahat — praktis untuk antrean semalaman. Hanya jika setidaknya satu unggahan selesai (bukan setelah Berhenti atau semuanya gagal). Mati secara bawaan. Sebagian firmware menolak mode istirahat; Anda akan diberi tahu jika PS5 ini menolak.",
"upload_wake_for_uploads_hint_ps5": "Saat ada unggahan yang menunggu PS5 ini dalam mode istirahat, kirim sinyal bangun dan lanjutkan begitu helper-nya kembali. Perlu pengaturan bangun untuk PS5 ini di layar Koneksi. Aktif secara bawaan.",
"install_path_fallback_hint_ps5": "Upaya terakhir untuk paket yang sudah ada di PS5 ini, ketika PS5 menolaknya dari penyimpanannya sendiri dan juga tidak bisa mengambilnya dari komputer ini. Hanya dipakai untuk game dasar yang belum terpasang, jadi tidak bisa menghapus apa pun. Belum terbukti: berhasil di firmware 11.20 dan ditolak di 13.60, jadi diatur untuk setiap PS5. Jika Anda mencobanya, tolong laporkan apakah berhasil.",
